1	const priceList: Record<string, number> = {
2	  sword: 100,
3	  amulet: 60,
4	  staff: 80,
5	  potion: 40,
6	  rune: 25,
7	  moonstone: 25,
8	};
9	
10	type Item = { type: string; material?: string; enchantment?: number; cursed?: boolean };
11	
12	const COMPONENT_BLOCK_SIZE = 3;
13	const COMPONENT_BLOCK_PRICE = 60;
14	
15	const COMPONENT_TYPES = ["rune", "moonstone"];
16	
17	const sumBy = <T>(items: T[], amount: (item: T) => number): number =>
18	  items.reduce((sum, item) => sum + amount(item), 0);
19	
20	const sumOfItemPrices = (items: Item[]): number =>
21	  sumBy(items, (item) => priceList[item.type]);
22	
23	const countOf = (type: string, items: Item[]): number =>
24	  items.filter((item) => item.type === type).length;
25	
26	const componentPremium = (type: string, items: Item[]): number => {
27	  const count = countOf(type, items);
28	  return count === COMPONENT_BLOCK_SIZE
29	    ? COMPONENT_BLOCK_PRICE
30	    : count * priceList[type];
31	};
32	
33	export const basePremium = (items: Item[]): number => {
34	  const nonComponents = items.filter(
35	    (item) => !COMPONENT_TYPES.includes(item.type),
36	  );
37	  const componentsTotal = COMPONENT_TYPES.reduce(
38	    (total, type) => total + componentPremium(type, items),
39	    0,
40	  );
41	  return sumOfItemPrices(nonComponents) + componentsTotal;
42	};
43	
44	const PROCESSING_FEE = 5;
45	const CURSE_SURCHARGE_RATE = 0.5;
46	const HIGH_ENCHANTMENT_RATE = 0.3;
47	const HIGH_ENCHANTMENT_THRESHOLD = 5;
48	const FIRST_INSURANCE_RATE = 0.1;
49	const LOYALTY_DISCOUNT_RATE = 0.2;
50	const LOYALTY_THRESHOLD_YEARS = 2;
51	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
52	
53	type Customer = { yearsWithMHPCO: number };
54	
55	const itemBasePremium = (item: Item): number => basePremium([item]);
56	
57	// A surcharge is a fraction of the item's own base premium, charged only when the item qualifies.
58	const surchargeWhen = (qualifies: boolean, item: Item, rate: number): number =>
59	  qualifies ? itemBasePremium(item) * rate : 0;
60	
61	const curseSurchargeFor = (item: Item): number =>
62	  surchargeWhen(item.cursed ?? false, item, CURSE_SURCHARGE_RATE);
63	
64	const hasEnchantmentAtLeast = (item: Item, threshold: number): boolean =>
65	  (item.enchantment ?? 0) >= threshold;
66	
67	const enchantSurchargeFor = (item: Item): number =>
68	  surchargeWhen(
69	    hasEnchantmentAtLeast(item, HIGH_ENCHANTMENT_THRESHOLD),
70	    item,
71	    HIGH_ENCHANTMENT_RATE,
72	  );
73	
74	const surchargesFor = (item: Item): number =>
75	  curseSurchargeFor(item) + enchantSurchargeFor(item);
76	
77	// Premiums round in MHPCO's favor — up. (Claim payouts round down, also in MHPCO's favor.)
78	const roundInFavorUp = (amount: number): number => Math.ceil(amount);
79	
80	// Claim payouts round in MHPCO's favor — down.
81	const roundInFavorDown = (amount: number): number => Math.floor(amount);
82	
83	const quotePremium = (
84	  items: Item[],
85	  customer: Customer,
86	  isFollowUp: boolean,
87	): number => {
88	  const policyBase = basePremium(items);
89	  const firstInsuranceSurcharge = policyBase * FIRST_INSURANCE_RATE;
90	  const loyaltyDiscount =
91	    customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS
92	      ? policyBase * LOYALTY_DISCOUNT_RATE
93	      : 0;
94	  const followUpDiscount = isFollowUp ? policyBase * FOLLOW_UP_DISCOUNT_RATE : 0;
95	  const policyCharges =
96	    policyBase + firstInsuranceSurcharge - loyaltyDiscount - followUpDiscount;
97	
98	  const itemSurcharges = sumBy(items, surchargesFor);
99	
100	  return roundInFavorUp(policyCharges + itemSurcharges + PROCESSING_FEE);
101	};
102	
103	const insuranceValueList: Record<string, number> = {
104	  sword: 1000,
105	  amulet: 600,
106	  staff: 800,
107	  potion: 400,
108	  rune: 250,
109	  moonstone: 250,
110	};
111	
112	const CAP_MULTIPLIER = 2;
113	const DEDUCTIBLE = 100;
114	const HIGH_ENCHANTMENT_PAYOUT_THRESHOLD = 8;
115	const HIGH_ENCHANTMENT_PAYOUT_RATE = 0.5;
116	
117	const insuranceSum = (items: Item[]): number =>
118	  sumBy(items, (item) => insuranceValueList[item.type]);
119	
120	// The cap is derived from the unmodified insurance value, independent of premium modifiers.
121	const initialCap = (items: Item[]): number => insuranceSum(items) * CAP_MULTIPLIER;
122	
123	type Damage = { itemType: string; amount: number };
124	
125	const isHighlyEnchanted = (item: Item | undefined): boolean =>
126	  item !== undefined &&
127	  hasEnchantmentAtLeast(item, HIGH_ENCHANTMENT_PAYOUT_THRESHOLD);
128	
129	const coveredAmountFor = (damage: Damage, insuredItem: Item | undefined): number =>
130	  isHighlyEnchanted(insuredItem)
131	    ? damage.amount * HIGH_ENCHANTMENT_PAYOUT_RATE
132	    : damage.amount;
133	
134	const reimbursementFor = (damage: Damage, items: Item[]): number => {
135	  const insuredItem = items.find((item) => item.type === damage.itemType);
136	  return coveredAmountFor(damage, insuredItem) - DEDUCTIBLE;
137	};
138	
139	type Incident = { cause: string; damages: Damage[] };
140	
141	type QuoteStep = { op: "quote"; items: Item[] };
142	type ClaimStep = { op: "claim"; policy: number; incident: Incident };
143	type Step = QuoteStep | ClaimStep;
144	type Scenario = { customer: Customer; steps: Step[] };
145	
146	type Policy = { items: Item[]; remainingCap: number };
147	type QuoteResult = { premium: number };
148	type ClaimResult = { payout: number; remainingCap: number };
149	type StepResult = QuoteResult | ClaimResult;
150	
151	export const runScenario = (scenario: Scenario): { results: StepResult[] } => {
152	  const policies: Record<number, Policy> = {};
153	  let quoteCount = 0;
154	
155	  const handleQuote = (step: QuoteStep, index: number): QuoteResult => {
156	    const isFollowUp = quoteCount > 0;
157	    quoteCount += 1;
158	    policies[index] = {
159	      items: step.items,
160	      remainingCap: initialCap(step.items),
161	    };
162	    return { premium: quotePremium(step.items, scenario.customer, isFollowUp) };
163	  };
164	
165	  const handleClaim = (step: ClaimStep): ClaimResult => {
166	    const policy = policies[step.policy];
167	    const payout = roundInFavorDown(
168	      sumBy(step.incident.damages, (damage) =>
169	        reimbursementFor(damage, policy.items),
170	      ),
171	    );
172	    policy.remainingCap -= payout;
173	    return { payout, remainingCap: policy.remainingCap };
174	  };
175	
176	  const results = scenario.steps.map((step, index): StepResult =>
177	    step.op === "quote" ? handleQuote(step, index) : handleClaim(step),
178	  );
179	
180	  return { results };
181	};
