const surchargeWhen = (qualifies: boolean, item: Item, rate: number): number =>
  qualifies ? itemBasePremium(item) * rate : 0;

const curseSurchargeFor = (item: Item): number =>
  surchargeWhen(item.cursed ?? false, item, CURSE_SURCHARGE_RATE);

const hasEnchantmentAtLeast = (item: Item, threshold: number): boolean =>
  (item.enchantment ?? 0) >= threshold;

const enchantSurchargeFor = (item: Item): number =>
  surchargeWhen(
    hasEnchantmentAtLeast(item, HIGH_ENCHANTMENT_THRESHOLD),
    item,
    HIGH_ENCHANTMENT_RATE,
  );

